{
 "summary": {
  "es": "国《くに》のことを最後《さいご》に決《き》める力《ちから》は、国民《こくみん》にあります（国民主権《こくみんしゅけん》）。そのもとで、選挙《せんきょ》でえらんだ代表《だいひょう》が決《き》めることが、もとになっています。一部《いちぶ》では、国民《こくみん》が直接《ちょくせつ》決《き》めるしくみも組《く》み合《あ》わせています。",
  "hs": "国民主権（政治を最終的に決める力が国民にあること）のもとで、選挙で選んだ代表者が決めることを基本にしています。あわせて、一部では国民が直接決める制度も組み合わせています。"
 },
 "blocks/0/text": {
  "es": "選挙《せんきょ》のとき以外《いがい》にも、国《くに》が決《き》めようとしているルールに、意見《いけん》をつたえる方法《ほうほう》はある？",
  "hs": "選挙のとき以外にも、国が決めようとしているルールに意見を伝える方法はある？"
 },
 "blocks/1/text": {
  "es": "日本国《にほんこく》憲法《けんぽう》は、はじめの文《ぶん》（前文《ぜんぶん》）で「主権《しゅけん》が国民《こくみん》に存《そん》することを宣言《せんげん》」しています。国《くに》のことを最後《さいご》に決《き》める力《ちから》は国民《こくみん》にある、とはっきり言《い》っているのです。第《だい》1条《じょう》でも、天皇《てんのう》の地位《ちい》が「主権《しゅけん》の存《そん》する日本国民《にほんこくみん》の総意《そうい》に基《もとづ》く」としています。主権《しゅけん》を持《も》つ日本国民《にほんこくみん》みんなの考《かんが》えにもとづく、という意味《いみ》です（国民主権《こくみんしゅけん》）。",
  "hs": "日本国憲法は前文で「主権が国民に存することを宣言」しています。第1条でも、天皇の地位が「主権の存する日本国民の総意に基く」（主権を持つ日本国民全体の意思にもとづく）としています（国民主権）。"
 },
 "blocks/3/text": {
  "es": "総務省《そうむしょう》は、多数決《たすうけつ》を「民主政治《みんしゅせいじ》の原則《げんそく》」としています。そして、「人々《ひとびと》の意見《いけん》を集約《しゅうやく》し、決定《けってい》する際《さい》に用《もち》いる方法《ほうほう》」と説明《せつめい》しています。みんなの意見《いけん》をまとめて、決《き》めるときに使《つか》う方法《ほうほう》、という意味《いみ》です。あわせて、少《すく》ない方《ほう》の意見《いけん》を大切《たいせつ》にすることも、民主政治《みんしゅせいじ》の原則《げんそく》とされています。",
  "hs": "総務省は多数決を「民主政治の原則」とし、「人々の意見を集約し、決定する際に用いる方法」と説明しています。あわせて、少数意見を尊重することも民主政治の原則とされています。"
 },
 "blocks/4/text": {
  "es": "衆議院《しゅうぎいん》と参議院《さんぎいん》の話《はな》し合《あ》いは、ふつう、出席《しゅっせき》した議員《ぎいん》の半分《はんぶん》より多《おお》くの賛成《さんせい》で決《き》めます（憲法《けんぽう》第《だい》56条《じょう》）。憲法《けんぽう》を変《か》える案《あん》を出《だ》すには、それぞれの議院《ぎいん》の、全部《ぜんぶ》の議員《ぎいん》の3分《ぶん》の2以上《いじょう》の賛成《さんせい》がいります。法律《ほうりつ》の案《あん》を衆議院《しゅうぎいん》でもう一度《いちど》決《き》める（再《さい》可決《かけつ》）には、出席《しゅっせき》した議員《ぎいん》の3分《ぶん》の2以上《いじょう》の賛成《さんせい》がいります。",
  "hs": "両議院の議事は、原則として出席議員の過半数（半分より多く）で決まります（憲法第56条）。憲法改正の発議には各議院の総議員の3分の2以上、法律案の衆議院での再可決には出席議員の3分の2以上が必要です。"
 },
 "blocks/5/items/0": {
  "es": "選挙《せんきょ》での投票《とうひょう》（憲法《けんぽう》第《だい》15条《じょう》）",
  "hs": "選挙での投票（憲法第15条）"
 },
 "blocks/5/items/1": {
  "es": "請願《せいがん》（国《くに》や役所《やくしょ》へのおねがい）（憲法《けんぽう》第《だい》16条《じょう》）",
  "hs": "請願《せいがん》（国などへの要望）（憲法第16条）"
 },
 "blocks/5/items/2": {
  "es": "国《くに》の決《き》まりの案《あん》について、広《ひろ》く意見《いけん》を集《あつ》める手《て》つづき（パブリックコメント）に、意見《いけん》を出《だ》すこと",
  "hs": "意見公募手続《いけんこうぼてつづき》（パブリックコメント：国の決まりの案に広く意見を求める手続き）への意見の提出"
 },
 "blocks/5/items/3": {
  "es": "役所《やくしょ》の文書《ぶんしょ》を見《み》せてほしいと、求《もと》めること（開示《かいじ》請求《せいきゅう》）",
  "hs": "行政文書（役所の文書）の開示｜請求《せいきゅう》（見せてほしいと求めること）"
 }
}
